using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        // Breaking change 1: EF Core 9 renamed the discriminator property
        // from "Discriminator" to "$type". Preserve the old name so existing
        // documents are still found.
        modelBuilder.Entity<Blog>().HasDiscriminator<string>("Discriminator");

        // Breaking change 2: EF Core 9 changed the id format from
        // "EntityType|Key" to just "Key". Preserve the old format so
        // existing documents with ids like "Blog|1" remain accessible.
        modelBuilder.Entity<Blog>().HasPartitionKey(b => b.Id);
        modelBuilder.Entity<Blog>().Property(b => b.Id)
            .HasJsonPropertyName("id")
            .ToJsonProperty("id");
        modelBuilder.Entity<Blog>().UseETagConcurrency();

        // Breaking change 3: HasIndex() on Cosmos now throws at model
        // validation instead of being silently ignored. Removed the
        // unsupported HasIndex call that was here previously.
    }

    protected override void OnConfiguring(DbContextOptionsBuilder optionsBuilder)
    {
        base.OnConfiguring(optionsBuilder);
    }
}
class Blog { public string Id { get; set; } public string Name { get; set; } }

